def count_even_odd_palindromes(n):
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    even = 0
    odd = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even += 1
            else:
                odd += 1

    return (even, odd)
```

